#include <stdio.h>

#define LIMIT 20
#define SQUARE(x) ((x) * (x))

int main(void)
{
    int value = 3;
    printf("%d %d\n", LIMIT, SQUARE(value + 1));
    return 0;
}

#include <stdio.h>

#define STRINGIFY(x) #x
#define JOIN(a, b) a ## b

int main(void)
{
    int lab_score = 19;
    printf("%s = %d\n", STRINGIFY(lab_score), JOIN(lab_, score));
    return 0;
}

#include <stdio.h>

static inline int square(int value)
{
    return value * value;
}

int main(void)
{
    int count = 3;
    int result = square(count++);
    printf("%d %d\n", result, count);
    return 0;
}

